import importlib.util
from pathlib import Path

import pytest

from polyinference.config import AgentConfig
from polyinference.domain import Assignment, SeniorProposal
from polyinference.workspace_contracts import relative_path


def test_runtime_wire_schemas_match_design():
    from polyinference.contracts import ContractBundle
    from polyinference.workspace_contracts import CoreExamples

    root = Path(__file__).resolve().parents[1]
    # Compare Python schemas under the same installed Pydantic release. Frozen JSON
    # was generated by an older release that duplicated const as enum.
    path = root / "design-docs/langgraph-agent/contracts.py"
    spec = importlib.util.spec_from_file_location("design_wire_for_test", path)
    module = importlib.util.module_from_spec(spec)
    import sys

    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    assert ContractBundle.model_json_schema() == module.ContractBundle.model_json_schema()
    import json

    examples = json.loads((root / "design-docs/simplified-os/core-examples.json").read_text())
    CoreExamples.model_validate(examples)
    ContractBundle.model_validate_json((root / "design-docs/langgraph-agent/examples.json").read_text())


@pytest.mark.parametrize("path", ["/etc/passwd", "../a", "a/../b", ".git/config", "a/.GIT/x", "a\\b", "C:x"])
def test_bad_paths(path):
    with pytest.raises(ValueError):
        relative_path(path)


def test_cycle_rejected():
    def task(name, dep):
        return Assignment(
            task_id=name,
            objective="bounded change",
            write_paths=["a.py"],
            checks=["syntax"],
            dependencies=[dep],
        )

    with pytest.raises(ValueError, match="cycle"):
        SeniorProposal(goal="bad", tasks=[task("a", "b"), task("b", "a")])


def test_opaque_native_coding_rejected(config):
    value = config.model_dump()
    value["local"]["protocol"] = "codex_proxy"
    with pytest.raises(ValueError, match="Opaque"):
        AgentConfig.model_validate(value)
